      const p = primary;
      const g = (kind, min = 1) => required(groups[kind] || [], kind, min);
      const t = key => text(p[key], key);
      const n = (key, min = 0, max = 1e12, integer = false) => num(p[key], key, min, max, integer);
      const d = key => date(p[key], key);
